const KEY='flip7-score-v1';
const colors=['#eac585','#b7cbb6','#edb39b','#bdc2df','#d9c3de','#c4d9cf','#e2d899','#b9d4e0'];
const $=s=>document.querySelector(s), escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,names=['','',''],target=200,editing=null,toastTimer;
try{const s=JSON.parse(localStorage.getItem(KEY));if(s?.players?.length&&Array.isArray(s.rounds)&&s.draft?.length===s.players.length&&s.rounds.every(r=>r.length===s.players.length&&r.every(Number.isInteger))&&Number.isInteger(s.target)&&s.target>0)state=s}catch{}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{$('#save-state').textContent='Sauvegarde indisponible sur cet appareil'}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function avatar(n,i){return `<span class="avatar" style="--color:${colors[i%colors.length]}">${escape(n.trim().slice(0,1).toUpperCase()||String(i+1))}</span>`}
function totals(){return state.players.map((_,i)=>state.rounds.reduce((a,r)=>a+r[i],0))}
function winners(){const t=totals(),max=Math.max(...t);return max>=state.target?t.map((v,i)=>v===max?i:-1).filter(i=>i>=0):[]}
function render(){if(!state)return setup();const t=totals(),rank=state.players.map((name,i)=>({name,i,total:t[i]})).sort((a,b)=>b.total-a.total),w=winners(),won=w.length===1;
$('#main').innerHTML=`<div class="game-top"><div><div class="eyebrow">Vengeance · ${state.players.length} joueurs</div><h1>Que le meilleur gagne.</h1><p>Objectif ${state.target} points · ${state.rounds.length} manche${state.rounds.length>1?'s':''} jouée${state.rounds.length>1?'s':''}</p></div><button class="quiet" id="new-game">Nouvelle partie</button></div>${won?`<div class="win"><div class="eyebrow">Partie terminée</div><h2>${escape(state.players[w[0]])} remporte la partie !</h2><p>${t[w[0]]} points. Une revanche ?</p><button class="quiet" id="rematch">Rejouer avec les mêmes joueurs</button></div>`:w.length>1?'<div class="win"><h2>Égalité en tête !</h2><p>Jouez une nouvelle manche avec tous les joueurs pour vous départager.</p></div>':''}<div class="game-grid"><section class="panel"><div class="section-top"><h2>${editing!==null?'Modifier la manche '+(editing+1):'Manche '+(state.rounds.length+1)}</h2><span class="tag">${editing!==null?'Correction':'À vous de jouer'}</span></div>${won&&editing===null?'<p class="muted">Les scores sont enregistrés. Retrouvez le détail des manches ci-dessous.</p>':`<form id="round-form"><div class="round-rows">${state.players.map((n,i)=>`<div class="round-row">${avatar(n,i)}<label for="score-${i}">${escape(n)}</label><input class="score-input" id="score-${i}" data-player="${i}" aria-label="Score de ${escape(n)}" type="number" step="1" min="-999" max="999" inputmode="numeric" placeholder="—" value="${escape(currentDraft()[i])}" required><div class="round-actions"><button type="button" class="chip" data-zero="${i}">Sauté · 0</button><button type="button" class="chip" data-bonus="${i}">Flip 7 · +15</button></div></div>`).join('')}</div><div class="round-bottom"><button class="primary wide" type="submit"><span>${editing!==null?'Enregistrer la correction':'Valider la manche'}</span><span class="arrow">↗</span></button>${editing!==null?'<button class="quiet" type="button" id="cancel-edit">Annuler la correction</button>':''}<p class="hint">Saisissez les scores finaux, malus compris. « Flip 7 » ajoute 15 au score saisi ; un second appui les retire.</p></div></form>`}</section><section class="panel standings-panel"><div class="section-top"><h2>Le classement</h2><span class="tag">${state.target} pts à atteindre</span></div><div class="standings">${rank.map((p,j)=>`<div class="${j===0&&p.total>0?'leader':''}"><div class="standing-head"><span class="rank">${j>0&&rank[j-1].total===p.total?'=':j+1}</span>${avatar(p.name,p.i)}<span class="standing-name">${escape(p.name)}${j===0&&p.total>0?'<span class="leader-label">En tête</span>':''}</span><span class="score">${p.total} <small>pts</small></span></div><div class="bar"><div style="width:${Math.max(0,Math.min(100,p.total/state.target*100))}%"></div></div></div>`).join('')}</div></section></div><section class="history"><div class="section-top"><h2>Le fil de la partie</h2>${state.rounds.length?'<button class="quiet" id="undo">Annuler la dernière manche</button>':''}</div>${state.rounds.length?`<div class="table-scroll"><table><thead><tr><th>Manche</th>${state.players.map(n=>`<th>${escape(n)}</th>`).join('')}<th></th></tr></thead><tbody>${state.rounds.map((r,j)=>`<tr><td>${String(j+1).padStart(2,'0')}</td>${r.map(v=>`<td>${v}</td>`).join('')}<td><button data-edit="${j}" aria-label="Modifier la manche ${j+1}">Modifier</button></td></tr>`).reverse().join('')}</tbody></table></div>`:'<div class="empty">La première manche ouvre le bal.<br>Vos scores et vos corrections apparaîtront ici.</div>'}</section>`;
$('#new-game').onclick=()=>confirmAction('Une nouvelle partie ?','La partie actuelle sera remplacée.','Nouvelle partie',()=>{names=[...state.players];target=state.target;state=null;editing=null;save();render()});
$('#rematch')?.addEventListener('click',()=>confirmAction('Prêts pour la revanche ?','Les mêmes joueurs repartent de zéro.','Rejouer',()=>{state.rounds=[];state.draft=state.players.map(()=>'');state.bonuses=[];editing=null;save();render()}));
document.querySelectorAll('[data-player]').forEach(el=>el.oninput=()=>{currentDraft()[+el.dataset.player]=el.value;save()});
document.querySelectorAll('[data-zero]').forEach(el=>el.onclick=()=>{const i=+el.dataset.zero;currentDraft()[i]='0';state.bonuses=state.bonuses.filter(b=>b!==i);save();render()});
document.querySelectorAll('[data-bonus]').forEach(el=>{const i=+el.dataset.bonus;el.classList.toggle('active',state.bonuses.includes(i));el.setAttribute('aria-pressed',String(state.bonuses.includes(i)));el.onclick=()=>{const d=currentDraft(),v=d[i]===''?0:Number(d[i]);if(!Number.isInteger(v))return;const has=state.bonuses.includes(i);d[i]=String(v+(has?-15:15));state.bonuses=has?state.bonuses.filter(b=>b!==i):[...state.bonuses,i];save();render()}});
$('#round-form')?.addEventListener('submit',e=>{e.preventDefault();const values=currentDraft().map(Number);if(currentDraft().some(v=>v==='')||values.some(v=>!Number.isInteger(v)||Math.abs(v)>999))return toast('Renseignez un score entier pour chaque joueur.');if(editing!==null){state.rounds[editing]=values;editing=null;delete state.editDraft}else{state.rounds.push(values);state.draft=state.players.map(()=>'')}state.bonuses=[];save();render();toast('Scores enregistrés')});
document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>{editing=+el.dataset.edit;state.editDraft=state.rounds[editing].map(String);state.bonuses=[];render();$('#score-0').focus();window.scrollTo({top:0,behavior:'smooth'})});
$('#cancel-edit')?.addEventListener('click',()=>{editing=null;delete state.editDraft;state.bonuses=[];save();render()});
$('#undo')?.addEventListener('click',()=>confirmAction('Annuler la dernière manche ?','Ses scores seront retirés du classement et replacés dans la saisie.','Annuler la manche',()=>{state.draft=state.rounds.pop().map(String);state.bonuses=[];editing=null;save();render()}));
}
function currentDraft(){return editing===null?state.draft:state.editDraft}
function setup(){$('#main').innerHTML=`<div class="setup"><section class="intro"><div class="eyebrow">Votre carnet de partie</div><h1>Les cartes en main.<br>Les comptes ici.</h1><p>Moins de calculs, plus de revanche.<br>On s’occupe des points.</p><div class="art" aria-hidden="true"><div class="playing-card card-a" data-num="4">4</div><div class="playing-card card-b" data-num="7">7</div><div class="playing-card card-c" data-num="13">13</div><span class="art-caption">Un dernier tour… et on s’arrête ?</span></div></section><section class="panel"><div class="panel-top"><h2>Autour de la table</h2><span class="tag">Vengeance</span></div><p class="subtitle">Qui tente sa chance aujourd’hui ?</p><form id="setup-form"><div class="players-inputs">${names.map((n,i)=>`<div class="player-input">${avatar(n,i)}<input maxlength="24" aria-label="Nom du joueur ${i+1}" placeholder="Joueur ${i+1}" value="${escape(n)}" data-name="${i}"><button type="button" class="remove" data-remove="${i}" aria-label="Retirer le joueur ${i+1}" ${names.length<=1?'disabled':''}>×</button></div>`).join('')}</div><button type="button" class="add" id="add" ${names.length>=18?'disabled':''}>+ Ajouter un joueur</button><div class="settings"><label for="target">Objectif de la partie <span class="muted">· points</span></label><input type="number" id="target" value="${target}" min="1" max="9999" step="1" inputmode="numeric" required></div><button class="primary wide" type="submit"><span>C’est parti</span><span class="arrow">↗</span></button></form><p class="hint">Un seul appareil pour toute la table. Votre partie reste ici, même si vous fermez la page.</p></section></div>`;
document.querySelectorAll('[data-name]').forEach(el=>el.oninput=()=>{names[+el.dataset.name]=el.value;el.previousElementSibling.textContent=el.value.trim().slice(0,1).toUpperCase()||+el.dataset.name+1});$('#target').oninput=e=>target=Number(e.target.value);document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{names.splice(+el.dataset.remove,1);setup()});$('#add').onclick=()=>{names.push('');setup();document.querySelector('[data-name="'+(names.length-1)+'"]').focus()};$('#setup-form').onsubmit=e=>{e.preventDefault();if(!Number.isInteger(target)||target<1||target>9999)return;const players=names.map((n,i)=>n.trim()||'Joueur '+(i+1));if(new Set(players.map(n=>n.toLocaleLowerCase())).size!==players.length)return toast('Choisissez un nom différent pour chaque joueur.');state={players,target,rounds:[],draft:players.map(()=>''),bonuses:[]};editing=null;save();render();window.scrollTo(0,0)};}
function dialog(html){const el=$('#modal');el.innerHTML=html;el.showModal();el.querySelector('[data-close]')?.addEventListener('click',()=>el.close())}
function confirmAction(title,body,label,fn){dialog(`<h2>${title}</h2><p>${body}</p><div class="dialog-actions"><button class="quiet" data-close>Retour</button><button class="primary" id="confirm">${label}</button></div>`);$('#confirm').onclick=()=>{$('#modal').close();fn()}}
$('#help').onclick=()=>dialog(`<div class="eyebrow">Mode d’emploi</div><h2>Les points, simplement.</h2><p>À la fin de chaque manche, saisissez le score final de chaque joueur, après application des cartes spéciales et des malus. Les scores négatifs sont acceptés pour vos parties en mode Sans pitié.</p><p><b>Sauté · 0</b> remplit un zéro. <b>Flip 7 · +15</b> ajoute le bonus au nombre saisi : utilisez-le uniquement si ce bonus n’est pas déjà inclus.</p><p>En mode Sans pitié, si vous choisissez de retirer 15 points à un adversaire, saisissez directement les scores finaux concernés.</p><p>À ${state?.target||target} points, le meilleur total gagne. Une égalité en tête prolonge la partie. Vous pouvez corriger une manche depuis l’historique.</p><p>Les données restent dans ce navigateur et ne sont pas synchronisées entre appareils. Pour l’avoir sous la main : menu du navigateur → « Ajouter à l’écran d’accueil ».</p><p><a href="https://flip-7.com/flip7-vengeance/" target="_blank" rel="noopener">Consulter les règles officielles ↗</a></p><p class="hint">Compteur indépendant, sans affiliation avec les éditeurs de Flip 7.</p><button class="primary wide" data-close>Compris</button>`);
if(state){state.bonuses=Array.isArray(state.bonuses)?state.bonuses:[];delete state.editDraft}render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
